import time
import datetime

def set_reminder(reminder_time_str, reminder_text):
    try:
        reminder_time = datetime.datetime.strptime(reminder_time_str, '%H')
        now = datetime.datetime.now()
        reminder_time = reminder_time.replace(year=now.year, month=now.month, day=now.day)
        if reminder_time < now:
            reminder_time += datetime.timedelta(days=1)

        wait_time = (reminder_time - now).total_seconds()
        if wait_time > 0:
            time.sleep(wait_time)
            print(reminder_text)
        else:
            print("Reminder time has already passed.")
    except ValueError:
        print("Invalid time format. Please use HH (e.g., 08 for 8 AM or 20 for 8 PM).")


set_reminder("08", "Go to sleep!")
